from pathlib import Path
import os,json,subprocess,hashlib
root=Path("/home/appontrack/public_html/saas/mobile")
assert os.getuid()==2379 and root.is_dir() and not root.is_symlink()
files={"call_event.php":"<?php
declare(strict_types=1);
require __DIR__.'/common.php';
require __DIR__.'/call_ledger.php';
mobile_require_device();
if ($_SERVER['REQUEST_METHOD']!=='POST') mobile_json(['ok'=>false,'error'=>'POST_only'],405);
$raw=file_get_contents('php://input',false,null,0,4097);
if (!is_string($raw) || strlen($raw)>4096) mobile_json(['ok'=>false,'error'=>'event_too_large'],413);
$event=json_decode($raw,true);
if (!is_array($event))mobile_json(['ok'=>false,'error'=>'invalid_json'],400);
try {
    mobile_json(ontrack_call_event($event,MOBILE_STORE.'/calls'));
}catch(InvalidArgumentException $e){
    mobile_json(['ok'=>false,'error'=>$e->getMessage()],422);
}catch(Throwable $e){
    error_log('ontrack call ledger: '.$e->getMessage());
    mobile_json(['ok'=>false,'error'=>'call_ledger_unavailable'],503);
}
","contacts_file_api.php":"<?php
declare(strict_types=1);
require __DIR__.'/common.php';
require __DIR__.'/pilot_workspace.php';
require __DIR__.'/pilot_import_file.php';
mobile_require_device();
if($_SERVER['REQUEST_METHOD']!=='POST')mobile_json(['ok'=>false,'error'=>'method_not_allowed'],405);
if(($_POST['confirmed']??'')!=='1'||($_POST['consent']??'')!=='1')mobile_json(['ok'=>false,'error'=>'explicit_confirmation_required'],422);
$file=$_FILES['contacts']??null;
if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||
    !is_string($file['tmp_name']??null)||!is_uploaded_file($file['tmp_name']))mobile_json(['ok'=>false,'error'=>'file_required'],422);
$size=(int)($file['size']??0);
if($size<1||$size>1048576)mobile_json(['ok'=>false,'error'=>'invalid_file_size'],413);
$name=(string)($file['name']??'');
if(strlen($name)>160||!preg_match('/\\.(csv|txt|xlsx)$/iD',$name))mobile_json(['ok'=>false,'error'=>'file_type'],422);
try{
    $rows=pilot_file_rows($file['tmp_name'],$name);
    if(!$rows)mobile_json(['ok'=>false,'error'=>'empty_file'],422);
    $counts=pilot_import_contacts($rows);
    mobile_json(['ok'=>true,'counts'=>$counts]);
}catch(InvalidArgumentException $e){
    mobile_json(['ok'=>false,'error'=>'invalid_file_contents'],422);
}catch(Throwable $e){
    mobile_json(['ok'=>false,'error'=>'file_import_failed'],500);
}
"}
for name,source in files.items():
 assert name in ("call_event.php","contacts_file_api.php")
 path=root/name;data=source.encode("utf-8")
 if path.exists():
  assert not path.is_symlink() and path.read_bytes()==data, "Existing differs "+name
 else:
  with os.fdopen(os.open(str(path),os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o644),"wb") as out:out.write(data)
 lint=subprocess.run(["/usr/local/bin/php","-l",str(path)],capture_output=True,text=True,timeout=8)
 assert lint.returncode==0,lint.stderr
 print(json.dumps({"file":name,"sha256":hashlib.sha256(data).hexdigest(),"lint":"PASS"}))
existing=root/"calls.php"
assert existing.is_file() and not existing.is_symlink()
lint=subprocess.run(["/usr/local/bin/php","-l",str(existing)],capture_output=True,text=True,timeout=8)
print(json.dumps({"file":"calls.php","existing_sha256":hashlib.sha256(existing.read_bytes()).hexdigest(),"lint":"PASS" if lint.returncode==0 else "FAIL","preserved":True}))
assert lint.returncode==0
